static double Calc(double a, double b, char op) {
  if(op=='+') return a+b;
  if(op=='-') return a-b;
  if(op=='*') return a*b;
  if(op=='/') return a/b;
  return 0;
}
Console.WriteLine(Calc(10, 2, '/'));

using System.Collections.Generic;
class ToDo {
  public List<string> detyrat = new List<string>();
  public void Shto(string d) { detyrat.Add(d); }
}
static void Main() {
  ToDo t = new ToDo();
  t.Shto("Studim");
  t.Shto("Gjumë");
  Console.WriteLine(t.detyrat[0]);
}

using System.Collections.Generic;
class ToDo {
  public List<string> detyrat = new List<string>() { "Studim" };
  public void Perfundo(string d) { detyrat.Remove(d); }
}
static void Main() {
  ToDo t = new ToDo();
  t.Perfundo("Studim");
  Console.WriteLine(t.detyrat.Count);
}

